import { afterEach, expect, it, vi } from 'vitest'
import { selectTodos } from './todos'
import type { Todo } from '../types'

afterEach(() => vi.useRealTimers())

it('selects only unfinished tasks due before the current local calendar day', () => {
  vi.useFakeTimers()
  vi.setSystemTime(new Date(2026, 10, 25, 12))
  const base: Todo = {
    id: 1, title: 'Overdue API task', description: '', priority: 'medium',
    completed: false, due_date: '2026-11-24',
    created_at: '2026-11-01T12:00:00Z', updated_at: '2026-11-01T12:00:00Z',
  }
  const todos: Todo[] = [
    base,
    { ...base, id: 2, completed: true },
    { ...base, id: 3, due_date: '2026-11-25' },
    { ...base, id: 4, due_date: '2026-11-26' },
    { ...base, id: 5, due_date: null },
  ]
  expect(selectTodos(todos, 'overdue', '', 'newest')).toEqual([base])
  expect(todos).toHaveLength(5)
})

it('combines overdue status with case-insensitive search and priority sorting', () => {
  vi.useFakeTimers()
  vi.setSystemTime(new Date(2026, 10, 25, 12))
  const low: Todo = {
    id: 1, title: 'API cleanup', description: '', priority: 'low',
    completed: false, due_date: '2026-11-24',
    created_at: '2026-11-01T12:00:00Z', updated_at: '2026-11-01T12:00:00Z',
  }
  const high: Todo = { ...low, id: 2, title: 'Release', description: 'API documentation', priority: 'high' }
  const unrelated: Todo = { ...low, id: 3, title: 'Shopping' }
  const todos = [low, unrelated, high]
  expect(selectTodos(todos, 'overdue', ' api ', 'priority')).toEqual([high, low])
  expect(todos).toEqual([low, unrelated, high])
})

import { render, screen } from '@testing-library/react'
import userEvent from '@testing-library/user-event'
import { expect, it, vi } from 'vitest'
import { TodoFilters } from './TodoFilters'

vi.mock('../../../design-system', () => import('../../../design-system/mocks'))

it('offers the overdue filter and forwards its selected value', async () => {
  const onFilterChange = vi.fn()
  render(<TodoFilters filter="all" search="" sort="newest" onFilterChange={onFilterChange} onSearchChange={vi.fn()} onSortChange={vi.fn()} />)
  const user = userEvent.setup()
  await user.selectOptions(screen.getByLabelText('Status'), 'overdue')
  expect(screen.getByRole('option', { name: 'Overdue' })).toBeInTheDocument()
  expect(onFilterChange).toHaveBeenCalledWith('overdue')
})
